-- Generated by `make contracts` from contracts/cdc_haicviz_cdi.odcs.yaml. Do not edit: change the contract and regenerate.
-- Business rules from the contract only: total rows, renamed labels, partial places, flag meanings,
-- then the conformed condition, place and time keys (conformedDimensions). Nothing is removed or
-- changed: each rule adds a column beside the published values.
with stg as (
    select * from {{ ref('stg_cdc_haicviz_cdi') }}
),

ruled as (
    select
      stg.*,
      coalesce((viewby = 'Total' AND series = 'Total'), false) AS "is_total_row"
    from stg
),

keyed as (
    select
    ruled.*,
    'Emerging Infections Program catchment areas combined' AS "_p_label",
    NULL AS "_p_whole",
    NULL AS "_p_decl_key",
    'USA' AS "_p_decl_parent",
    'the EIP catchment areas combined, not the whole United States (geographyBasis)' AS "_p_decl_note",
    NULL AS "_p_note",
    try_cast(ruled."yearname" AS BIGINT) AS "_t_year",
    NULL AS "_t_week"
  from ruled
)

select
  keyed.* exclude ("_p_label", "_p_whole", "_p_decl_key", "_p_decl_parent", "_p_decl_note", "_p_note", "_t_year", "_t_week"),
  CAST(CASE WHEN 'Clostridioides difficile infection' IS NULL THEN NULL ELSE 'cdc_haicviz_cdi:' || 'Clostridioides difficile infection' END AS VARCHAR) AS "condition_key",
  CAST('Clostridioides difficile infection' AS VARCHAR) AS "condition_label",
  CAST(NULL AS VARCHAR) AS "condition_case_status",
  CAST(NULL AS VARCHAR) AS "condition_case_subtype",
  CAST(CASE WHEN keyed._p_label IS NULL THEN NULL WHEN keyed._p_decl_key IS NOT NULL THEN keyed._p_decl_key WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) THEN CASE WHEN coalesce(keyed._p_decl_parent, keyed._p_whole) IS NULL THEN NULL ELSE coalesce(keyed._p_decl_parent, keyed._p_whole) || '/cdc_haicviz_cdi:' || trim(regexp_replace(lower(trim(keyed._p_label)), '[^a-z0-9]+', '-', 'g'), '-') END ELSE keyed._p_whole END AS VARCHAR) AS "place_key",
  CAST(keyed._p_label AS VARCHAR) AS "place_label",
  CAST(CASE WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) THEN coalesce(keyed._p_decl_parent, keyed._p_whole) ELSE NULL END AS VARCHAR) AS "place_parent_key",
  CAST(coalesce((keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)), false) AS BOOLEAN) AS "place_is_partial",
  CAST(CASE WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) AND coalesce(keyed._p_decl_parent, keyed._p_whole) IS NOT NULL THEN coalesce(keyed._p_decl_note, keyed._p_note) WHEN (CASE WHEN keyed._p_label IS NULL THEN NULL WHEN keyed._p_decl_key IS NOT NULL THEN keyed._p_decl_key WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) THEN CASE WHEN coalesce(keyed._p_decl_parent, keyed._p_whole) IS NULL THEN NULL ELSE coalesce(keyed._p_decl_parent, keyed._p_whole) || '/cdc_haicviz_cdi:' || trim(regexp_replace(lower(trim(keyed._p_label)), '[^a-z0-9]+', '-', 'g'), '-') END ELSE keyed._p_whole END) IS NULL THEN 'unresolved: the contract does not declare this place label and it is not a name or code in the Census code files' ELSE NULL END AS VARCHAR) AS "place_note",
  CAST(CASE WHEN (CASE WHEN keyed._p_label IS NULL THEN NULL WHEN keyed._p_decl_key IS NOT NULL THEN keyed._p_decl_key WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) THEN CASE WHEN coalesce(keyed._p_decl_parent, keyed._p_whole) IS NULL THEN NULL ELSE coalesce(keyed._p_decl_parent, keyed._p_whole) || '/cdc_haicviz_cdi:' || trim(regexp_replace(lower(trim(keyed._p_label)), '[^a-z0-9]+', '-', 'g'), '-') END ELSE keyed._p_whole END) IS NULL THEN 'unresolved' WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) THEN 'partial_area' ELSE 'resolved' END AS VARCHAR) AS "place_status",
  CAST(CAST(NULL AS BIGINT) AS BIGINT) AS "mmwr_year",
  CAST(CAST(NULL AS BIGINT) AS BIGINT) AS "mmwr_week",
  CAST(CASE WHEN keyed._t_year IS NULL THEN NULL ELSE 'Y' || CAST(keyed._t_year AS VARCHAR) END AS VARCHAR) AS "time_key",
  CAST('year' AS VARCHAR) AS "time_grain",
  CAST('the surveillance year as published (yearname); which date places a case in a year is not stated on data.cdc.gov' AS VARCHAR) AS "date_basis"
from keyed
